if __name__=='__main__':
 repeat.OUT=OUT;stability=repeat.check();mode=json.loads((OUT/'runtime_selection.json').read_text())['mode']
 reports=json.loads((OUT/'test_results.json').read_text());selection=json.loads((OUT/'selection.json').read_text());goal=json.loads((OUT/'goal_assessment.json').read_text());comparison=json.loads((OUT/'comparison.json').read_text());protocol=json.loads((OUT/'protocol.json').read_text());audit=json.loads((OUT/'fresh_audit.json').read_text());prompt=read_prompt(OUT/'best_candidate.py')
 assert digest(prompt)==reports['selected']['prompt_hash']==selection['selected']['prompt_hash']
