 for field in ['bucket','origin','model','scenario']:
  lines+=['',f'| {field} | Previous | Selected | Selected balanced accuracy |','|---|---:|---:|---:|']
  for k,m in new['by_'+field].items():lines.append(f"| {k} | {hit(old['by_'+field][k])} | {hit(m)} | {pct(m['balanced_accuracy'])} |")
 lo,hi=comparison['group_bootstrap_delta95'];lines+=['',f"Corrected {comparison['improved']} errors; introduced {comparison['regressed']}. Exploratory group-bootstrap 95% interval for balanced-accuracy change: [{100*lo:.1f}, {100*hi:.1f}] percentage points. This includes sampling uncertainty, not future-model guarantees.",'',f"Repeatability diagnostic: {stability['stable_cases']}/{stability['n']} preselected cases stable across three calls; unavailable calls {stability['unavailable_calls']}. Failed operational checks: {', '.join(goal['failed']) or 'none'}. Thresholds were retained unchanged from round 3.",'','## Use','','From `pangram_opus`, with OPENROUTER_API_KEY in the environment:','','```sh','.venv/bin/python classify.py example.txt','```','','Returns `{"slop": true}` or `{"slop": false}`. Provider refusal is an error (exit 2), never silently human. `best_prompt.txt` is the calibrated prompt; `inference_system.txt` includes the contract; `request_template.json` and `inference_config.json` reproduce runtime. One classified text per request.','', 'Full artifacts: `round5/selection.json`, `round5/test_results.json`, `round5/results.json`, `round5/goal_assessment.json`. Prior working artifacts are backed up with `round5/previous_`. Corpus provenance is retained; Brown noncommercial research and source terms continue to apply.','', 'New human sources include Brown news and hobbies/practical prose because unused short government and review documents were insufficient. This source choice was made before fresh teacher labels or classifier outcomes; source/topic groups remain disjoint.','', '## Cumulative budget','']
 for k,v in costs.items():lines.append(f"- {k}: conservative ${v['conservative_total']:.2f} / ${v['limit']:.0f}, including margin and pending reservations.")
 lines+=['','The same session ledger is used throughout; do not reset it. Pangram costs are estimated from billed-word units, not a bank statement. API keys are not stored in artifacts.']
 lines+=['', 'Exploratory group-bootstrap 95% intervals for the selected classifier: agreement '+str([round(100*x,1) for x in uncertainty['agreement95']])+'%; balanced accuracy '+str([round(100*x,1) for x in uncertainty['balanced_accuracy95']])+'%. The operational thresholds concern point estimates; these intervals show their uncertainty.']
 for p in [ROOT/'README.md',OUT/'REPORT.md']:p.write_text('\n'.join(lines)+'\n')
 print(json.dumps({'selected':new['overall'],'goal_met':goal['met'],'budget':costs},indent=2))
